		}
		handler = null;
		upgradeHandler = null;
		settingsHandler = null;
		refreshInventoryForUpgradeProcessing();
		onInventoryHandlerRefresh.run();
		if (previousUpgradeHandler != null) {
			previousUpgradeHandler.notifyRefreshCallbacks();
		}
		refreshUuidStorageWrapperContents();
	}

